import dataUrl from './explore-airports.json?url';
import { foldSearch, registerPlaces, type ExplorePlace } from './explore-places';

// Airport search for the Explore picker: jump to an airport by ICAO or
// IATA code or by name ("KMSP", "ATW", "heathrow").
//
// explore-airports.json is generated by scripts/build-airports.py from
// OurAirports (public domain; do not hand-edit): every large and medium
// airport worldwide plus US small fields with an ICAO code, big airports
// first. At about 200 KB compressed it is too big to bundle, so it is
// fetched the first time the picker opens. Each airport becomes an
// ordinary Explore place (`apt_<icao>`) registered in the place catalog,
// so picking one is a feed switch like any city.

export interface Airport {
  icao: string;
  /** Empty when the airport has none. */
  iata: string;
  name: string;
  city: string;
  place: ExplorePlace;
  /** Folded name + city, matched for queries that are not a code. */
  haystack: string;
}

export const AIRPORT_PLACE_PREFIX = 'apt_';

export function airportPlaceId(icao: string): string {
  return `${AIRPORT_PLACE_PREFIX}${icao.toLowerCase()}`;
}

/** "Appleton International Airport" -> "Appleton Intl"; a second name after " / " is dropped. */
export function shortAirportName(name: string): string {
  return name
    .split(' / ')[0]!
    .replace(/\bInternational\b/g, 'Intl')
    .replace(/\bRegional\b/g, 'Rgnl')
    .replace(/\bMunicipal\b/g, 'Muni')
    .replace(/\s+Airport\b/g, '')
    .trim();
}

type Row = [string, string, string, string, string, number, number, number];

/** Parse the generated file; malformed rows are dropped. */
export function decodeAirports(raw: unknown): Airport[] {
  const rows = (raw as { airports?: Row[] } | null)?.airports;
  if (!Array.isArray(rows)) return [];
  const out: Airport[] = [];
  for (const row of rows) {
    if (!Array.isArray(row) || row.length < 8) continue;
    const [icao, iata, name, city, country, lat, lon, altFt] = row;
    if (typeof icao !== 'string' || !Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    out.push({
      icao,
      iata,
      name,
      city,
      haystack: foldSearch(`${name} ${city}`),
      place: {
        id: airportPlaceId(icao),
        // The code leads: it is what was typed and what a pilot reads.
        name: `${icao} · ${city || shortAirportName(name)}`,
        country,
        // Regions only group the curated list; airports are never listed whole.
        region: 'north_america',
        lat,
        lon,
        altFt: Number.isFinite(altFt) ? altFt : 0,
      },
    });
  }
  return out;
}

/**
 * Airports matching a folded query, best first: an exact ICAO or IATA
 * code, then a code that starts with the query, then (three or more
 * characters) a name or city containing it. Ties keep the list's own
 * order, which puts large airports first.
 */
export function searchAirports(airports: readonly Airport[], query: string, limit: number): Airport[] {
  const q = query.trim();
  if (q.length < 2) return [];
  const code = q.toUpperCase().replace(/\s+/g, '');
  const tiers: Airport[][] = [[], [], []];
  for (const a of airports) {
    if (a.icao === code || a.iata === code) tiers[0]!.push(a);
    else if (a.icao.startsWith(code) || (a.iata !== '' && a.iata.startsWith(code))) tiers[1]!.push(a);
    else if (q.length >= 3 && a.haystack.includes(q)) tiers[2]!.push(a);
    if (tiers[0]!.length >= limit) break;
  }
  return [...tiers[0]!, ...tiers[1]!, ...tiers[2]!].slice(0, limit);
}

let airports: Airport[] | null = null;
let loading: Promise<readonly Airport[]> | null = null;

/** Loaded airports, or null until loadAirports() has finished. */
export function getAirports(): readonly Airport[] | null {
  return airports;
}

/** Fetch once and register every airport as an Explore place. Resolves empty on failure (retried next call). */
export function loadAirports(): Promise<readonly Airport[]> {
  if (airports) return Promise.resolve(airports);
  // Inside the chain so an environment without fetch rejects instead of throwing.
  loading ??= Promise.resolve()
    .then(() => fetch(dataUrl))
    .then((res) => {
      if (!res.ok) throw new Error(`airport data: HTTP ${res.status}`);
      return res.json() as Promise<unknown>;
    })
    .then((raw) => {
      airports = decodeAirports(raw);
      registerPlaces(airports.map((a) => a.place));
      return airports as readonly Airport[];
    })
    .catch((err: unknown) => {
      console.warn('[explore] could not load airports', err);
      loading = null;
      return [];
    });
  return loading;
}
